def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    total_players = 1 + len(alive_opponents)
    tightness = float(total_players * WATER_REQ) / max(1.0, supply)

    urgent_prev_bids = []
    all_prev_bids = []
    rich_aggressive = []

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            all_prev_bids.append(float(bid))
            opp_urgent = (opp.get('hp', 10) <= 3) or (opp.get('no_water_days', 0) >= 2)
            if opp_urgent:
                urgent_prev_bids.append(float(bid))
            if opp.get('budget', 0) > budget and float(bid) >= DAILY_SALARY * 0.9:
                rich_aggressive.append(float(bid))

    highest_prev = max(all_prev_bids) if all_prev_bids else 0.0
    highest_urgent_prev = max(urgent_prev_bids) if urgent_prev_bids else highest_prev
    pressure_bid = highest_urgent_prev
    if rich_aggressive:
        pressure_bid = max(pressure_bid, max(rich_aggressive))

    emergency = (hp <= 2) or (no_water_days >= 2)
    caution = (hp <= 4) or (no_water_days >= 1)

    if emergency:
        bid = max(DAILY_SALARY * 0.95, pressure_bid + 2.0)
        return float(max(0.0, min(budget, bid)))

    if tightness >= 2.8:
        if caution:
            bid = max(DAILY_SALARY * 0.82, pressure_bid + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.58, min(pressure_bid + 1.0, DAILY_SALARY * 0.88))
    elif tightness >= 2.2:
        if caution:
            bid = max(DAILY_SALARY * 0.68, min(pressure_bid + 1.0, DAILY_SALARY * 0.82))
        else:
            bid = max(DAILY_SALARY * 0.45, min(pressure_bid * 0.72, DAILY_SALARY * 0.7))
    else:
        if caution:
            bid = DAILY_SALARY * 0.42
        else:
            bid = DAILY_SALARY * 0.22

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.9

    min_safe = 0.0
    if caution and supply <= 18:
        min_safe = DAILY_SALARY * 0.4
    bid = max(bid, min_safe)

    if budget < DAILY_SALARY * 0.5 and not emergency:
        bid = min(bid, budget * 0.55)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_agents = len(alive_opponents) + 1

    # Estimate fair share bid
    fair_share_bid = (supply / num_agents) * 5

    # Look at yesterday's pressure
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If supply is low, bid aggressively to ensure survival
        if supply < 18:
            return min(my_status['budget'], max(max_prev * 1.05, 75))
        # If supply is high, try to save budget
        return min(my_status['budget'], max(fair_share_bid, 40))

    return min(my_status['budget'], 60)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    supply = day_context['supply']

    # Get yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Determine our urgency
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # If desperately thirsty (critical hp), bid high
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.9
        if prev_bids:
            target = max(target, max(prev_bids) + 10)
        return min(budget, target)

    # If supply is low, more competition
    if supply < MIN_SUPPLY + 3:
        target = DAILY_SALARY * 0.7
        if prev_bids:
            target = max(target, max(prev_bids) + 5)
        return min(budget, target)

    # Normal day: use opponent history if available
    if prev_bids:
        # We want to be slightly above the median to avoid overbidding
        median_bid = sorted(prev_bids)[int(len(prev_bids) // 2)]
        # But if our hp is decent, bid moderately
        target = median_bid + 5
        # Cap at 85% salary to preserve budget
        target = min(target, DAILY_SALARY * 0.85)
        return min(budget, target)

    # No history: use supply-based default
    # Lower supply -> higher bid
    default = DAILY_SALARY * (1 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
    default = max(default, DAILY_SALARY * 0.3)
    return min(budget, default)
